import{_ as t,o as s,c as l,a4 as n}from"./chunks/framework.BE47AOxC.js";const g=JSON.parse(`{"title":"ADR-0072 — Un libellé pour toute clé i18n : le catalogue entier servi à l'admin, le texte libre accepté là où l'agent saisit une clé","description":"Extrait de docs/adr/0072-libelles-de-toutes-les-cles.md, publié tel quel à chaque construction du site.","frontmatter":{"title":"ADR-0072 — Un libellé pour toute clé i18n : le catalogue entier servi à l'admin, le texte libre accepté là où l'agent saisit une clé","description":"Extrait de docs/adr/0072-libelles-de-toutes-les-cles.md, publié tel quel à chaque construction du site."},"headers":[],"relativePath":"developpeurs/adr/0072-libelles-de-toutes-les-cles.md","filePath":"developpeurs/adr/0072-libelles-de-toutes-les-cles.md"}`),o={name:"developpeurs/adr/0072-libelles-de-toutes-les-cles.md"};function i(a,e,r,c,d,u){return s(),l("div",null,[...e[0]||(e[0]=[n('<h1 id="adr-0072--un-libellé-pour-toute-clé-i18n--le-catalogue-entier-servi-à-ladmin-le-texte-libre-accepté-là-où-lagent-saisit-une-clé" tabindex="-1">ADR-0072 — Un libellé pour toute clé i18n : le catalogue entier servi à l&#39;admin, le texte libre accepté là où l&#39;agent saisit une clé <a class="header-anchor" href="#adr-0072--un-libellé-pour-toute-clé-i18n--le-catalogue-entier-servi-à-ladmin-le-texte-libre-accepté-là-où-lagent-saisit-une-clé" aria-label="Permalink to &quot;ADR-0072 — Un libellé pour toute clé i18n : le catalogue entier servi à l&#39;admin, le texte libre accepté là où l&#39;agent saisit une clé {#adr-0072--un-libellé-pour-toute-clé-i18n--le-catalogue-entier-servi-à-ladmin-le-texte-libre-accepté-là-où-lagent-saisit-une-clé}&quot;">​</a></h1><p><strong>Date :</strong> 17 octobre 2026 <strong>Statut :</strong> Accepté <strong>Décideur :</strong> Sébastien Rapuzzi (Product Owner) <strong>Source :</strong> issue #31 (lot 24) ; arbitrages du Product Owner du 17/10/2026 (source unique côté serveur, catalogue servi à l&#39;admin, périmètre de toutes les familles, texte libre là où l&#39;agent saisit, tests d&#39;exhaustivité par famille et par propriétaire, français d&#39;abord) <strong>Amende :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0071-libelles-cote-serveur">ADR-0071</a>, décisions n°2 (borne de 200 à 400 caractères), n°4 (le libellé n&#39;est plus rendu à côté de chaque clé dans chaque réponse : l&#39;admin lit un catalogue servi une fois), n°6 (l&#39;admin résout par un composable unique) et n°7 (le périmètre passe des permissions et rôles à toutes les familles de clés) <strong>Complète :</strong> <a href="/teuthis-cms-distribution/developpeurs/adr/0002-frontiere-core-plugins">ADR-0002</a> (une extension n&#39;écrit que dans son espace <code>plugins.&lt;sa clé&gt;.</code>)</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte {#contexte}&quot;">​</a></h2><p>L&#39;ADR-0071 a donné un libellé aux permissions et aux rôles, et a posé le mécanisme pour le reste (<code>LabelResolver.label</code>). Il a laissé ouverte l&#39;action « remplir les autres familles de clés ». Or l&#39;admin affichait encore des clés brutes presque partout : l&#39;aide d&#39;un champ (<code>help_key</code>), le libellé d&#39;un filtre ou d&#39;un bouton (<code>label_key</code>), le message « liste vide » (<code>empty_message_key</code>), le résumé d&#39;une extension (<code>summary_key</code>), la finalité d&#39;un cookie (<code>purpose_key</code>), le motif d&#39;une relecture (<code>reason_key</code>), la note d&#39;un fournisseur d&#39;identité (<code>notes_key</code>), le nom d&#39;une tâche d&#39;IA. Un agent qui compose une vue liste lit <code>listing.filtre.thematique</code> là où il attend « Thématique ».</p><p>Deux défauts s&#39;ajoutaient. D&#39;abord, <strong>la voie choisie en 0071 — rendre le libellé à côté de la clé dans chaque réponse — ne passe pas à l&#39;échelle</strong> : il faudrait modifier chaque route, chaque schéma de réponse et chaque type de l&#39;admin, famille par famille, pour des clés qui se trouvent à l&#39;intérieur de configurations imbriquées (le filtre n°3 d&#39;une vue liste d&#39;un type de contenu d&#39;une extension). Ensuite, <strong>l&#39;agent saisit lui-même des clés</strong> (éditeur de vue liste, éditeur de schéma, règles de cycle de vie) : lui demander d&#39;inventer <code>listing.filtre.date_de_l_evenement</code> pour afficher « Date de l&#39;événement » est une contrainte de développeur, que le serveur ne peut d&#39;ailleurs pas honorer, faute de libellé pour une clé qu&#39;il n&#39;a jamais vue.</p><h2 id="décision" tabindex="-1">Décision <a class="header-anchor" href="#décision" aria-label="Permalink to &quot;Décision {#décision}&quot;">​</a></h2><p><strong>1. La source reste unique et côté serveur.</strong> Le Core écrit ses libellés dans <code>app/i18n/core.py</code>, chaque extension dans le champ <code>labels</code> de son manifeste (ADR-0071, décisions 1 à 3, inchangées). Aucune table de libellés n&#39;existe dans l&#39;admin ni dans le front.</p><p><strong>2. Une route sert le catalogue entier d&#39;une langue.</strong> <code>GET /api/v1/i18n/labels?lang=fr</code> rend <code>{language, version, count, labels: {clé: libellé}}</code> pour l&#39;organisation de la session : les libellés du <strong>Core</strong> et ceux des extensions <strong>actives</strong> sur cette organisation — ni ceux d&#39;une extension seulement déclarée ou désactivée, ni ceux d&#39;une autre organisation.</p><ul><li>Authentifiée, sans permission particulière : tout agent connecté lit les intitulés qu&#39;il voit.</li><li>Repli : langue inconnue → français ; clé non traduite dans la langue demandée → son libellé français, clé par clé (<code>LabelResolver.labels_of</code>). <code>lang</code> prime sur <code>Accept-Language</code>.</li><li>Sans N+1 : une seule lecture (les extensions actives de l&#39;organisation, par l&#39;index <code>(organization_id, status)</code>), le reste en mémoire. Un test compte les requêtes avant et après l&#39;installation de quatre extensions : le nombre ne bouge pas.</li><li>Bornée : 500 libellés par langue et par extension au plus, 400 caractères chacun.</li><li>Cachable : <code>ETag</code> dérivé du contenu (aussi <code>version</code> dans le corps), <code>Cache-Control: private, no-cache</code>, 304 sur <code>If-None-Match</code>.</li><li>Une clé que le catalogue ne connaît pas n&#39;y figure pas : c&#39;est ce qui permet de distinguer, côté admin, un libellé connu d&#39;un texte libre.</li></ul><p><strong>3. Un seul composable dans l&#39;admin.</strong> <code>useLibelles()</code> charge le catalogue <strong>une fois par session</strong> (après <code>/auth/me</code>, par le middleware global), le garde (<code>useState</code>, rendu serveur compris), le recharge quand l&#39;agent installe, active, désactive ou désinstalle une extension, et l&#39;oublie à la déconnexion. <code>libelle(valeur)</code> rend le libellé d&#39;une clé connue, sinon <strong>la valeur telle quelle</strong> (texte libre ou clé inconnue) : jamais un trou, jamais une erreur. Le texte est inséré par interpolation (échappé), jamais en HTML. <code>LabelledKey</code> passe par lui, de sorte que toute clé — pas seulement les permissions et rôles — se montre « libellé, puis clé en texte secondaire » là où l&#39;écran s&#39;adresse à un administrateur ou à un développeur (rôles, fournisseurs, tâches d&#39;IA, finalités de cookie) ; l&#39;aide de champ, le motif et le résumé d&#39;extension se montrent résolus, sans clé, là où l&#39;écran s&#39;adresse à un agent qui rédige.</p><ul><li>Le résumé d&#39;une extension <strong>non installée</strong> n&#39;est pas dans le catalogue de l&#39;organisation : <code>GET /plugins</code> rend donc <code>summary_label</code> à côté de <code>summary_key</code> (le seul cas où le libellé reste à côté de la clé, parce que l&#39;écran liste aussi ce qui n&#39;est pas installé).</li></ul><p><strong>4. Le texte libre est accepté là où l&#39;agent saisit une clé — et seulement là.</strong> Un type <code>LabelKeyOrText</code> (<code>app/listing/config.py</code>) remplace <code>I18nKey</code> pour : le libellé d&#39;un filtre, le libellé et le titre d&#39;un en-tête de vue liste, le message « liste vide » (<code>ListingConfig</code>), l&#39;aide d&#39;un champ et le corps d&#39;un champ d&#39;aide (<code>help_key</code>, <code>body_key</code> des champs de schéma), le motif d&#39;une relecture (<code>reason_key</code> de <code>RequestReviewAction</code>). Valeur : une clé i18n <strong>ou</strong> un texte d&#39;<strong>une ligne</strong>, <strong>400 caractères au plus</strong>, espaces de bord retirés, <strong>sans chevrons</strong> (<code>&lt;</code> et <code>&gt;</code> refusés : le texte est affiché tel quel, jamais interprété). Les éditeurs de l&#39;admin (<code>LibelleLibreField</code>) disent « clé de traduction ou texte », appliquent la même règle avant l&#39;envoi (erreur liée par <code>aria-describedby</code>) et montrent en <strong>aperçu</strong> le libellé résolu.</p><ul><li><strong>Les manifestes d&#39;extension restent en clés strictes.</strong> <code>ListingConfig</code>, le schéma de contenu et les règles de cycle de vie sont aussi ceux des manifestes ; <code>PluginManifest</code> parcourt donc son arbre et refuse tout <code>label_key</code>, <code>title_key</code>, <code>empty_message_key</code>, <code>help_key</code>, <code>body_key</code> ou <code>reason_key</code> qui n&#39;est pas une clé (« une extension déclare une clé i18n, pas un texte libre »). Raison : un texte libre n&#39;a pas de libellé dans le catalogue, donc n&#39;est pas traduisible, et le test d&#39;exhaustivité (décision 6) ne saurait pas le relever.</li><li>Les clés qui ne sont pas saisies par l&#39;agent (finalité de cookie, question d&#39;utilité, gabarits) restent des clés.</li></ul><p><strong>5. La borne d&#39;un libellé passe de 200 à 400 caractères</strong> (<code>MAX_LABEL_LENGTH</code>), pour le manifeste comme pour le Core : une aide de champ ou un message « liste vide » tient en une ou deux phrases. Une ligne, non vide, espaces de bord retirés : inchangé.</p><p><strong>6. Un libellé pour toute clé du Core, et un test par famille et par propriétaire.</strong></p><ul><li><strong>Les libellés du Core</strong> (<code>app/i18n/core.py</code>) couvrent les 113 clés non courriel du Core : permissions et rôles (33, déjà là), fournisseurs d&#39;identité (3 libellés, 2 notes), tâches d&#39;IA (14), boutons du bandeau de cookies (3), finalités de cookie (17), mentions de licence des polices (15), recherche (facettes, messages, annonces : 9), vues liste (2), cycle de vie et comptes (5 motifs, 1 question d&#39;utilité), formulaires (2), déclaration d&#39;accessibilité (4 niveaux, 1 avertissement), politique de données (1 avertissement), inscription (1). Les textes que le Core écrit déjà ailleurs — finalités de cookie (<code>COOKIE_PURPOSE_TEXTS</code>) et mentions de licence des polices (<code>font_attribution</code>) — ne sont pas recopiés : <code>LabelResolver</code> les reprend de leur source, pour qu&#39;il n&#39;y ait qu&#39;une rédaction.</li><li><strong>Le collecteur</strong> (<code>tests/test_libelles_exhaustifs.py</code>) parcourt chaque manifeste livré comme un arbre de modèles pydantic, et le Core par ses registres, par une lecture de son code source (<code>ast</code> : littéraux passés à un champ de libellé, constantes <code>…_KEY</code>) et par les familles construites par f-string (niveaux de conformité, polices). Tout champ <code>*_key</code> est <strong>classé</strong> : libellé, gabarit de courriel (exclu : <code>subject_key</code>, <code>body_key</code> des notifications, <code>template_key</code>, <code>notification_template_key</code>, qui ont leur catalogue <code>notification_texts</code>) ou identifiant (exclu : <code>role_key</code>, <code>content_type_key</code>…). Un champ <code>*_key</code> inconnu <strong>fait échouer</strong> un test : on ne peut pas ajouter une famille de clés sans décider si elle porte un libellé.</li><li><strong>Un test par <code>(propriétaire, famille)</code></strong>, dont l&#39;identifiant contient la clé de l&#39;extension (<code>pytest -k &lt;clé&gt;</code>) : chaque clé a un libellé français, <strong>dans le Core plus cette extension seule</strong> (une extension ne peut pas compter sur le libellé d&#39;une autre). Un second test par <code>(propriétaire, famille)</code> tient le style (libellé court sans point final ; aide, résumé, finalité, note, message : phrase avec point final ; 400 caractères au plus). Un dernier refuse un libellé du Core sans clé dans le code (orphelin).</li></ul><p><strong>7. Français d&#39;abord, structure prête pour l&#39;anglais.</strong> Inchangé : <code>LabelResolver.labels_of</code> et la route replient clé par clé sur le français ; l&#39;anglais viendra comme une seconde entrée de <code>CORE_LABELS</code> et des <code>labels</code> des manifestes.</p><h2 id="alternatives-considérées" tabindex="-1">Alternatives considérées <a class="header-anchor" href="#alternatives-considérées" aria-label="Permalink to &quot;Alternatives considérées {#alternatives-considérées}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Pourquoi écartée</th></tr></thead><tbody><tr><td><strong>Continuer à rendre <code>label</code> à côté de chaque clé</strong> (voie de l&#39;ADR-0071)</td><td>Une famille, une route, un schéma, un type admin : des dizaines de modifications pour des clés enfouies dans des configurations (filtre n°3 d&#39;une vue d&#39;un type de contenu d&#39;une extension). Une clé saisie par l&#39;agent n&#39;aurait de toute façon aucun libellé à côté d&#39;elle.</td></tr><tr><td><strong>Une table de libellés dans l&#39;admin</strong></td><td>Écartée en 0071 et pour les mêmes raisons : elle ne connaîtrait ni les extensions tierces ni les clés ajoutées au Core, et divergerait du serveur.</td></tr><tr><td><strong>Un appel de résolution par clé (<code>GET /i18n/labels/{clé}</code>)</strong></td><td>Un aller-retour par clé affichée : le N+1 déplacé dans le navigateur.</td></tr><tr><td><strong>Servir le catalogue de toute la distribution</strong></td><td>Révèle à un agent les extensions qu&#39;il n&#39;a pas installées et alourdit la réponse pour rien. Le catalogue d&#39;une organisation suit ses extensions actives.</td></tr><tr><td><strong>Texte libre partout, y compris dans les manifestes</strong></td><td>Une extension livrée avec du texte en dur n&#39;est ni traduisible ni contrôlable par un test. La souplesse n&#39;est utile qu&#39;à qui saisit.</td></tr><tr><td><strong>Texte libre limité par un motif</strong> (lettres et espaces seulement)</td><td>Refuse « Prix (en €) » ou « Qu&#39;est-ce que c&#39;est ? » sans protéger de rien : l&#39;échappement à l&#39;affichage est la protection, le refus des chevrons une ceinture.</td></tr><tr><td><strong>Caractères HTML autorisés, assainis à l&#39;affichage</strong></td><td>Un assainisseur de plus à tenir à jour pour une ligne de texte. Refuser les chevrons coûte moins et ne se contourne pas.</td></tr><tr><td><strong>Un seul test d&#39;exhaustivité pour tout le Core et toutes les extensions</strong></td><td>Chaque agent qui écrit les libellés d&#39;une extension doit lancer le sien (<code>-k &lt;clé&gt;</code>) ; un test global rouge pendant des heures n&#39;indique rien.</td></tr></tbody></table><h2 id="conséquences" tabindex="-1">Conséquences <a class="header-anchor" href="#conséquences" aria-label="Permalink to &quot;Conséquences {#conséquences}&quot;">​</a></h2><p><strong>Positives</strong></p><ul><li>Toute clé du Core et des extensions livrées s&#39;affiche en français dans l&#39;admin ; l&#39;agent écrit « Date de l&#39;événement » dans un filtre au lieu d&#39;inventer une clé.</li><li>Ajouter une clé au Core, ou à un manifeste, sans écrire sa phrase fait échouer un test nommé d&#39;après la famille et le propriétaire.</li><li>Une nouvelle famille de clés ne passe pas inaperçue : le champ <code>*_key</code> non classé fait échouer le collecteur.</li><li>Un seul endroit côté admin (<code>useLibelles</code>) à faire évoluer pour l&#39;anglais, et un seul appel de plus par session.</li></ul><p><strong>Négatives</strong></p><ul><li><strong>Un texte libre n&#39;a pas de langue.</strong> Une vue en texte libre s&#39;affiche dans la langue où l&#39;agent l&#39;a écrite, quel que soit le lecteur ; la clé garde l&#39;avantage de la traduction. L&#39;éditeur le dit dans son aide et montre l&#39;aperçu pour que le choix soit conscient.</li><li><strong>Une réponse de plus à charger</strong> à l&#39;ouverture d&#39;une session (quelques milliers de libellés au plus), revalidée par <code>ETag</code>. Un rechargement est fait quand l&#39;agent installe ou retire une extension ; une extension activée par un autre agent n&#39;apparaît qu&#39;au prochain chargement de session.</li><li><strong>Un libellé est une affirmation</strong> sur ce que fait une clé : le test ne vérifie que sa présence et son style, pas son exactitude (comme en 0071).</li><li><strong>Des libellés repris de leur source</strong> (finalités de cookie, polices) suivent la forme de cette source : sans point final pour les premières, et la mention de licence d&#39;une police reprend la ponctuation du texte de droit d&#39;auteur (« Inc.. » pour l&#39;une d&#39;elles) — défaut de la source, à corriger là-bas.</li><li>Les gabarits de courriel restent hors périmètre : leurs clés ont leur propre catalogue.</li><li>Le front public et le site du projet n&#39;affichent aujourd&#39;hui aucune de ces clés (le front a ses propres textes, le site ne montre que les permissions et rôles) : ils ne sont pas modifiés. Si l&#39;un d&#39;eux affiche un jour une clé, il lira le libellé dans la réponse de l&#39;API qui la porte, sans vidage du catalogue complet.</li></ul><h2 id="actions-liées" tabindex="-1">Actions liées <a class="header-anchor" href="#actions-liées" aria-label="Permalink to &quot;Actions liées {#actions-liées}&quot;">​</a></h2><ul><li>[x] Mécanisme et libellés du Core : borne à 400 caractères, route <code>GET /api/v1/i18n/labels</code> (Core + extensions actives, repli français, <code>ETag</code>, sans N+1), composable <code>useLibelles</code> et <code>LabelledKey</code>, texte libre aux endroits de saisie (<code>LabelKeyOrText</code>, <code>LibelleLibreField</code>) et clés strictes dans les manifestes, libellés des 113 clés du Core, collecteur et tests d&#39;exhaustivité. — <code>apps/api/app/api/i18n_labels.py</code>, <code>apps/api/app/plugins/labels.py</code> (<code>labels_of</code>, <code>derived_core_labels</code>), <code>apps/api/app/i18n/{catalogue,core}.py</code>, <code>apps/api/app/listing/config.py</code> (<code>LabelKeyOrText</code>), <code>apps/api/app/plugins/manifest.py</code> (<code>_check_strict_label_keys</code>) ; admin : <code>composables/useLibelles.ts</code>, <code>server/api/i18n/labels.get.ts</code>, <code>components/libelles/LibelleLibreField.vue</code>, <code>components/rbac/LabelledKey.vue</code>, <code>components/fields/FieldFrame.vue</code>, <code>pages/plugins.vue</code> et les éditeurs de vue liste, de schéma et de règles. Preuves : <code>apps/api/tests/test_libelles_exhaustifs.py</code> (rouge sur le Core avant l&#39;écriture des libellés : 20 familles en échec, vert ensuite), <code>test_libelles_route.py</code> (8 tests : 401, Core, extensions actives, autre organisation, repli, <code>ETag</code>/304, zéro requête de plus, borne de 400), <code>test_libelles_texte_libre.py</code> (11 tests) ; <code>ruff</code>, <code>flake8</code>, <code>lint</code>, <code>typecheck</code> et <code>build</code> de l&#39;admin verts le 17/10/2026.</li><li>[x] Libellés des extensions livrées : un libellé français pour chaque clé de chacune des 29 extensions (aides de champ, filtres, actions, messages « liste vide », résumés, titres…), vérifié par <code>pytest tests/test_libelles_exhaustifs.py -k &lt;clé de l&#39;extension&gt;</code>. <strong>Fait le 17/10/2026</strong> (lot 24, issue #31) : 512 libellés écrits dans le champ <code>labels</code> des 29 manifestes (agents B, C, D1, D2). Preuve : <code>pytest tests/test_libelles_exhaustifs.py</code> vert pour chaque (extension, famille), 420 tests de libellés réussis.</li><li>[ ] Ajouter l&#39;anglais : une entrée <code>&quot;en&quot;</code> dans <code>CORE_LABELS</code> et dans les <code>labels</code> des extensions livrées ; <code>GET /api/v1/i18n/labels?lang=en</code> et <code>useLibelles</code> servent déjà la langue demandée avec repli français clé par clé (reste : choisir la langue de l&#39;agent connecté et la transmettre à <code>useLibelles</code>).</li></ul>',26)])])}const m=t(o,[["render",i]]);export{g as __pageData,m as default};
